/* ============ МАСТЕРСКИЕ СИРАКУЗ · 644 · «КРИПТАРИФМЫ: БУКВЫ ВМЕСТО ЦИФР» · 5–6 класс ============
   Цикл «Мастерские Сиракуз»: по одному олимпиадному приёму на урок. К 644-му
   листу в цикле уже были 626 (чётность), 627 (Дирихле), 628 (игры и стратегии),
   629 (инвариант), 630 (оценка и пример), 631 (крайний случай), 643 (двойной
   подсчёт), 645 (обратный ход), 646 (от противного) — и ни одного урока про
   криптарифмы. Перед работой тема проверена дважды: поиском по MVP/data
   (слов «криптарифм», «криптоарифм», «ребус» нет ни в одном листе) и замером
   по window.ARH_LESSONS в живом приложении. Номер 644 проверен так же: grep по
   MVP/data не находит ни одного листа с этим номером, а в живом каталоге
   ARH_LESSONS урока 644 нет (прежний лист с этим номером удалён).

   Главная мысль урока: в ребусе каждая буква — это ровно одна цифра, разные
   буквы — разные цифры, и ведущая буква числа не может быть нулём. Отсюда весь
   разбор: перенос из разряда в старший разряд становится новой буквой (и равен
   единице), а проверка идёт столбиком и таблицей «буква → цифра».

   Каждое задание — свой сюжет и свой рисунок. Двух одинаковых кадров нет:
   столбик ОДИН + ОДИН = МНОГО с таблицей букв, перенос-буква Д в ребусе
   УДАР + УДАР = ДРАКА, подсветка одной и той же буквы А в КНИГА + КНИГА = НАУКА,
   перестановка цифр в АБ + БА = 121, число из одинаковых цифр в АА + ББ = 110,
   ребус-ловушка АБ + А = ВВ, таблица двух решений для АБ + БА = 33 и финальный
   столбик ББ + ББ = ВВА.

   Все числовые ответы проверены перебором на Node (полный перебор всех
   расстановок цифр): ОДИН + ОДИН = МНОГО — ровно одно решение (6823);
   УДАР + УДАР = ДРАКА — ровно одно (8126); КНИГА + КНИГА = НАУКА — ровно пять
   (25160, 25310, 25360, 25410, 25460); АБ + БА = 121 — восемь решений (сумма
   А + Б = 11); АА + ББ = 110 — восемь решений (сумма А + Б = 10, пара 5 и 5
   отброшена: буквы разные); АБ + А = ВВ — решений нет вовсе; АБ + БА = 33 —
   ровно два (12 и 21); ББ + ББ = ВВА — ровно одно (А = 0, Б = 5, В = 1).
   Где решение не одно, это сказано в разборе прямо и перечислены все решения.

   Палитра и вёрстка. Лист живёт на общем бумажном листе RUPAPER
   (MVP/data/vis_ru.js), как 626–646: заголовок, рисунок, вопрос, варианты и
   разбор рисует движок, состояние лежит в CHS, счёт «верно/ошибок» — общий.
   Сами чертежи нарисованы на тёмном планшете цветами проекта — фон #0b1712,
   золото #d9a441, серебро текста #e8e0cc, приглушённое #cbb89a.
   Контраст пары «#e8e0cc на #0b1712» — 13,9 : 1, «#d9a441 на #0b1712» — 8,2 : 1,
   «#cbb89a на #0b1712» — 9,5 : 1, то есть заметно выше порога 4,5 : 1.

   Кегли внутри чертежей — только по шкале проекта: 14 · 16 · 20 · 24.
   Значков-эмодзи внутри SVG нет: клетки, кружки переносов, стрелки и подсветка
   нарисованы прямоугольниками, кругами, линиями и путями.
*/
(function(){
  const F = "Georgia,'Times New Roman',serif";
  const DEEP = '#0b1712', GOLD = '#d9a441', IVORY = '#e8e0cc', MUTE = '#cbb89a',
        RED = '#e86a5a', GREEN = '#8fd1a8',
        LINE = 'rgba(217,164,65,.65)', HAIR = 'rgba(217,164,65,.25)',
        FILL = 'rgba(217,164,65,.07)', FLAT = 'rgba(217,164,65,.18)';

  /* Холст 320 единиц: на телефоне рисунок ложится почти один к одному,
     поэтому 16 единиц читаются как 16 px, а не мельче. */
  const sv = (inner, h) =>
    `<svg viewBox="0 0 320 ${h}" width="100%" style="display:block;max-width:100%;font-variant-numeric:tabular-nums">${inner}</svg>`;
  const tx = (x, y, s, size, fill, anchor, w) =>
    `<text x="${x}" y="${y}" text-anchor="${anchor || 'middle'}" font-family="${F}" font-size="${size || 16}" fill="${fill || IVORY}"${w ? ` font-weight="${w}"` : ''}>${s}</text>`;
  const rect = (x, y, w, h, fill, stroke, rx, sw) =>
    `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx == null ? 4 : rx}" fill="${fill || 'none'}"` +
    `${stroke ? ` stroke="${stroke}" stroke-width="${sw || 1}"` : ''}/>`;
  const line = (x1, y1, x2, y2, c, w, dash) =>
    `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${c || LINE}" stroke-width="${w || 1}"${dash ? ` stroke-dasharray="${dash}"` : ''}/>`;
  const circ = (cx, cy, r, fill, stroke, w) =>
    `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${fill || 'none'}"${stroke ? ` stroke="${stroke}" stroke-width="${w || 1}"` : ''}/>`;

  /* Тёмный планшет под чертёж: один и тот же на всех рисунках листа. */
  const board = (h, inner) => rect(6, 6, 308, h - 12, DEEP, GOLD, 10) + inner;

  /* ── запись сложения в столбик ──
     XR — правый край столбика, CW — шаг разряда. CX(k) — центр разряда k,
     считая от единиц: k = 0 это единицы, k = 1 десятки и так далее.
     Строка столбика выравнивается по правому краю: последняя буква слова
     всегда стоит в разряде единиц. */
  const XR = 249, CW = 34;
  const CX = k => XR - CW / 2 - k * CW;
  const ряд = (s, y, size, fill) => String(s).split('').map((ch, i, a) =>
    tx(CX(a.length - 1 - i), y, ch, size || 24, fill || IVORY)).join('');
  /* Кружок переноса над разрядом: та же клетка, но маленькая и выше строки. */
  const перенос = (k, y, s, col) =>
    circ(CX(k), y, 10, FLAT, col || GOLD, 1.3) + tx(CX(k), y + 5, s, 14, col || GOLD);
  /* Черта под слагаемыми: от левого края самого широкого числа до правого. */
  const черта = (y, from, to) => line(from == null ? 82 : from, y, to == null ? 262 : to, y, GOLD, 1.6);
  /* Пустая клетка таблицы «буква → цифра»: буква стоит рядом, клетка пустая. */
  const клетка = (x, y, w, h, s, size, fill) =>
    rect(x, y, w, h, FILL, LINE, 5, 1.3) + (s ? tx(x + w / 2, y + h - 8, s, size || 20, fill || IVORY) : '');

  /* ================= 1. ОДИН + ОДИН = МНОГО =================
     Главный столбик урока: перенос из разряда тысяч даёт пятую букву М.
     Ответа на рисунке нет: видны только буквы, кружки переносов и пустая
     таблица «буква → цифра», которую ребёнок заполняет по шагам. */
  const один = () => {
    const h = 332;
    let s = tx(160, 26, 'буквы вместо цифр: одна буква — одна цифра', 14, MUTE);
    /* переносы над разрядами: из единиц в десятки, из десятков в сотни,
       из сотен в тысячи и из тысяч в новый пятый разряд (там стоит буква М) */
    s += перенос(1, 60, '?') + перенос(2, 60, '?') + перенос(3, 60, '?') + перенос(4, 60, 'М');
    s += ряд('ОДИН', 96);
    s += ряд('ОДИН', 130);
    s += tx(100, 130, '+', 20, GOLD);
    s += черта(142);
    s += ряд('МНОГО', 180);
    s += tx(160, 204, 'кружки над разрядами — это переносы', 14, MUTE);
    s += tx(160, 226, 'таблица «буква → цифра» — заполняй', 14, GOLD);
    const буквы = [['М', 'Н', 'О'], ['Г', 'Д', 'И']];
    буквы.forEach((row, i) => {
      const y = 240 + i * 32;
      row.forEach((L, j) => {
        const lx = 34 + j * 100;
        s += tx(lx + 13, y + 21, L, 20, GOLD);
        s += клетка(lx + 30, y, 36, 28);
      });
    });
    s += tx(160, 318, 'шесть клеток — шесть разных цифр', 14, MUTE);
    return sv(board(h, s), h);
  };

  /* ================= 2. УДАР + УДАР = ДРАКА =================
     Ловушка ребуса: буква Д стоит и в разряде сотен слова УДАР, и в старшем
     разряде ответа. Именно туда уходит перенос, а перенос равен единице.
     На рисунке перенос-буква соединён со своим местом в ответе штриховой
     линией: видно, что это одна и та же буква. */
  const удар = () => {
    const h = 336;
    let s = tx(160, 26, 'в ответе пять знаков — откуда лишний?', 14, MUTE);
    s += перенос(1, 58, '?') + перенос(2, 58, '?') + перенос(3, 58, '?');
    s += circ(CX(4), 58, 10, FLAT, RED, 1.5) + tx(CX(4), 63, 'Д', 14, RED);
    s += line(CX(4), 70, CX(4), 150, RED, 1, '4 4');
    s += ряд('УДАР', 96);
    s += ряд('УДАР', 130);
    /* Плюс уводим левее столбца CX(4): там сверху стоит кружок-перенос Д,
       а вниз идёт красная штриховая линия, и плюс на ней читался как клякса. */
    s += tx(66, 130, '+', 20, GOLD);
    s += черта(142);
    s += ряд('ДРАКА', 178);
    s += tx(160, 204, 'буква Д — и в слове УДАР, и в ответе', 14, MUTE);
    s += tx(160, 226, 'таблица «буква → цифра»', 14, GOLD);
    const буквы = [['У', 'Д', 'А'], ['Р', 'К']];
    буквы.forEach((row, i) => {
      const y = 240 + i * 32;
      row.forEach((L, j) => {
        const lx = 34 + j * 100;
        s += tx(lx + 13, y + 21, L, 20, GOLD);
        s += клетка(lx + 30, y, 36, 28);
      });
    });
    s += tx(160, 320, 'проверь, что все пять цифр разные', 14, MUTE);
    return sv(board(h, s), h);
  };

  /* ================= 3. КНИГА + КНИГА = НАУКА =================
     Подсвечены все три буквы А: две в слове КНИГА и одна в слове НАУКА.
     Одна и та же буква — одна и та же цифра; из этого и растёт разбор.
     Две нижние строки с пустыми клетками нужны, чтобы ребёнок выписал
     найденные числа и проверил каждое сложением. */
  const книга = () => {
    const h = 316;
    let s = tx(160, 26, 'буква А — и в КНИГА, и в НАУКА', 14, MUTE);
    s += перенос(1, 58, '?') + перенос(2, 58, '?') + перенос(3, 58, '?') + перенос(4, 58, '?');
    /* подсветка трёх букв А идёт под буквами, поэтому рисуется раньше */
    s += rect(CX(0) - 17, 72, 34, 30, FLAT, GOLD, 6, 1.2);
    s += rect(CX(0) - 17, 106, 34, 30, FLAT, GOLD, 6, 1.2);
    s += rect(CX(0) - 17, 154, 34, 30, FLAT, GOLD, 6, 1.2);
    s += ряд('КНИГА', 96);
    s += ряд('КНИГА', 130);
    s += tx(66, 130, '+', 20, GOLD);
    s += черта(142);
    s += ряд('НАУКА', 178);
    s += tx(160, 204, 'одна буква — одна и та же цифра', 14, MUTE);
    const строка = (y, слово) => {
      let g = tx(20, y + 20, слово + ' =', 16, IVORY, 'start');
      for (let j = 0; j < 5; j++) g += клетка(100 + j * 30, y, 26, 26);
      return g;
    };
    s += строка(228, 'КНИГА');
    s += строка(262, 'НАУКА');
    s += tx(160, 304, 'выпиши все числа и проверь сложением', 14, MUTE);
    return sv(board(h, s), h);
  };

  /* ================= 4. АБ + БА = 121 =================
     Число и его перевёртыш: цифры меняются местами, поэтому штриховые линии
     соединяют одинаковые буквы через строку. Ниже — запись ребуса числами:
     из неё видно, что сумма всегда делится на 11. */
  const перестановка = () => {
    const h = 298;
    let s = tx(160, 26, 'АБ и БА — цифры переставлены', 14, MUTE);
    s += line(CX(1), 100, CX(0), 118, HAIR, 1, '4 3');
    s += line(CX(0), 100, CX(1), 118, HAIR, 1, '4 3');
    s += ряд('АБ', 92);
    s += ряд('БА', 126);
    s += tx(168, 126, '+', 20, GOLD);
    s += черта(138, 152, 248);
    s += ряд('121', 176);
    s += rect(20, 202, 280, 56, FILL, GOLD, 8, 1.3);
    s += tx(160, 228, '11 · (А + Б) = 121', 20, IVORY);
    s += tx(160, 248, 'чему равна сумма А + Б?', 16, GOLD);
    s += tx(160, 284, 'решений несколько: перебери все пары', 14, MUTE);
    return sv(board(h, s), h);
  };

  /* ================= 5. АА + ББ = 110 =================
     Число из двух одинаковых цифр — это 11 · А. Рисунок ведёт к уравнению
     11 · (А + Б) = 110 и оставляет клетку для суммы: ловушка 55 + 55
     разбирается в тексте, а не в чертеже, чтобы ответ не был виден сразу. */
  const одинаковые = () => {
    const h = 302;
    let s = tx(160, 26, 'АА — это 11 · А: две одинаковые цифры', 14, MUTE);
    s += ряд('АА', 92);
    s += ряд('ББ', 126);
    s += tx(168, 126, '+', 20, GOLD);
    s += черта(138, 152, 248);
    s += ряд('110', 176);
    s += rect(20, 202, 280, 56, FILL, GOLD, 8, 1.3);
    s += tx(160, 228, '11 · (А + Б) = 110', 20, IVORY);
    s += tx(160, 248, 'чему равна сумма А + Б?', 16, GOLD);
    s += tx(160, 288, 'цифры у А и Б должны быть разными', 14, MUTE);
    return sv(board(h, s), h);
  };

  /* ================= 6. РЕБУС-ЛОВУШКА АБ + А = ВВ =================
     Подстановка Мишутки арифметически верна: 20 + 2 = 22. Красная линия
     соединяет две одинаковые цифры 2 у разных букв А и В, а перечёркнутый
     крест показывает, где именно нарушено правило ребуса. */
  const ловушка = () => {
    const h = 302;
    let s = tx(160, 26, 'проверяй не только сумму, но и буквы', 14, MUTE);
    s += ряд('АБ', 92);
    s += ряд('А', 126);
    s += tx(200, 126, '+', 20, GOLD);
    s += черта(138, 200, 248);
    s += ряд('ВВ', 176);
    const тройка = (lx, boxX, L, D) => {
      let g = rect(lx, 214, 30, 32, FILL, LINE, 5, 1.3);
      g += tx(lx + 15, 236, L, 20, GOLD);
      g += rect(boxX, 214, 34, 32, FLAT, GOLD, 5, 1.3);
      g += tx(boxX + 17, 238, D, 24, IVORY);
      return g;
    };
    s += тройка(30, 62, 'А', '2');
    s += тройка(134, 166, 'Б', '0');
    s += тройка(238, 270, 'В', '2');
    s += line(79, 256, 287, 256, RED, 1.2);
    s += line(175, 248, 191, 264, RED, 2);
    s += line(191, 248, 175, 264, RED, 2);
    s += tx(160, 286, 'разные буквы А и В — одна цифра 2', 14, RED);
    return sv(board(h, s), h);
  };

  /* ================= 7. АБ + БА = 33: НАЙДИ ВСЕ РЕШЕНИЯ =================
     Таблица на два решения: у ребуса их ровно два, и оба нужно назвать.
     В клетках пусто — числа вписывает ребёнок. */
  const все33 = () => {
    const h = 334;
    let s = tx(160, 26, 'решений может быть несколько — найди все', 14, MUTE);
    s += ряд('АБ', 92);
    s += ряд('БА', 126);
    s += tx(168, 126, '+', 20, GOLD);
    s += черта(138, 152, 248);
    s += ряд('33', 176);
    s += rect(20, 200, 280, 26, FLAT, LINE, 6, 1.2);
    s += tx(60, 218, 'буква', 14, GOLD);
    s += tx(150, 218, 'решение 1', 14, GOLD);
    s += tx(250, 218, 'решение 2', 14, GOLD);
    const строки = ['А', 'Б', 'число АБ'];
    строки.forEach((L, i) => {
      const y = 226 + i * 26;
      s += rect(20, y, 280, 26, FILL, HAIR, 0);
      s += line(100, y, 100, y + 26, HAIR, 1);
      s += line(200, y, 200, y + 26, HAIR, 1);
      s += tx(60, y + 18, L, 14, IVORY);
    });
    s += line(20, 200, 20, 304, LINE, 1.2);
    s += line(300, 200, 300, 304, LINE, 1.2);
    s += line(20, 304, 300, 304, LINE, 1.2);
    s += tx(160, 322, 'впиши оба решения и проверь', 14, MUTE);
    return sv(board(h, s), h);
  };

  /* ================= 8. ФИНАЛ: ББ + ББ = ВВА =================
     Последний ребус урока и три пустые клетки для цифр. Здесь ребёнок не
     только решает, но и объясняет, почему другой ответ невозможен. */
  const финал = () => {
    const h = 292;
    let s = tx(160, 26, 'финальный ребус: ББ + ББ = ВВА', 14, MUTE);
    s += перенос(1, 58, '?') + перенос(2, 58, '?');
    s += ряд('ББ', 92);
    s += ряд('ББ', 126);
    s += tx(168, 126, '+', 20, GOLD);
    s += черта(138, 152, 248);
    s += ряд('ВВА', 176);
    const ответ = (gx, L) => rect(gx + 32, 210, 36, 32, FILL, GOLD, 5, 1.3) + tx(gx + 14, 232, L, 20, GOLD);
    s += ответ(26, 'А') + ответ(132, 'Б') + ответ(238, 'В');
    s += tx(160, 274, 'объясни, почему других цифр быть не может', 14, GOLD);
    return sv(board(h, s), h);
  };

  const A = {
    один: один,
    удар: удар,
    книга: книга,
    перестановка: перестановка,
    одинаковые: одинаковые,
    ловушка: ловушка,
    все33: все33,
    финал: финал,
  };

  window.RUPAPER.mount({
    id: 644, ico: '🔤', brand: 'Мастерские Сиракуз', brandIco: null,
    title: 'Криптарифмы: буквы вместо цифр',
    src: 'Мастерские Сиракуз · 5–6 класс · Криптарифмы: буквы вместо цифр',
    source: 'Приём олимпиадной линии: криптарифм (ребус с буквами вместо цифр). Сюжеты и рисунки написаны для этого урока; каждое решение проверено полным перебором на Node, где решений несколько — они перечислены в разборе полностью.',
    subj: 'math', group: 'syra', img: 'img/archimedes.jpg',
    art: A,
    data: [
      {k:'один', type:'single', t:'Ребус ОДИН + ОДИН = МНОГО',
       q:'Одинаковые буквы — одинаковые цифры, разные буквы — разные цифры, первая буква числа не ноль. Расшифруй ребус: чему равно слово ОДИН?',
       opts:['6823', '6824', '6832', '13646'],
       ans:'6823',
       why:'Шаг 1. Смотрим на старший разряд суммы. Складывали два четырёхзначных числа, а в ответе пять знаков — значит, из разряда тысяч в новый пятый разряд перешёл перенос, и этот перенос записан буквой М. Перенос из разряда в следующий всегда равен 1, поэтому М = 1. Шаг 2. Разряд единиц: Н + Н = О. Сумма двух одинаковых цифр всегда чётная, значит О — чётная цифра: 0, 2, 4, 6 или 8. Обозначим перенос из единиц в десятки через c₁ (он равен 0 или 1), тогда 2Н = О + 10c₁. Шаг 3. Разряд тысяч: О + О + c₃ = Н + 10, где c₃ — перенос из сотен: в разряд тысяч пришёл перенос, а сам разряд тысяч отдал единицу дальше, поэтому Н = 2О + c₃ − 10. Шаг 4. Из шага 2 выразим О = 2Н − 10c₁ и подставим: Н = 4Н − 20c₁ + c₃ − 10, то есть 3Н = 10 + 20c₁ − c₃. Если c₁ = 0, получаем 3Н = 10 − c₃; подходит только c₃ = 1, тогда 3Н = 9 и Н = 3, а О = 2Н = 6. Если c₁ = 1, получаем 3Н = 30 − c₃, то есть 29 или 30, а на 3 ни то, ни другое не делится. Итак, Н = 3, О = 6, переноса из единиц нет (c₁ = 0), а перенос из сотен есть (c₃ = 1). Шаг 5. Разряд сотен: Д + Д + c₂ = О + 10c₃ = 6 + 10 = 16, то есть 2Д + c₂ = 16. При c₂ = 1 слева нечётное число, а 16 чётное, значит c₂ = 0 и Д = 8. Шаг 6. Разряд десятков: И + И + c₁ = Г + 10c₂, то есть 2И = Г. Заполняем таблицу «буква → цифра»: М = 1 (шаг 1), Н = 3 и О = 6 (шаг 4), Д = 8 (шаг 5). Свободные цифры — 0, 2, 4, 5, 7, 9. Буквам И и Г нужны две разные цифры, причём Г = 2И. Проверяем по порядку: И = 0 даёт Г = 0 — одна цифра у двух букв, нельзя; И = 2 даёт Г = 4 — подходит; И = 4 даёт Г = 8, но 8 уже занята буквой Д; И = 5 даёт Г = 10 — это не цифра. Значит, И = 2 и Г = 4, и других вариантов нет. Шаг 7. Проверка: 6823 + 6823 = 13646. Сверяем буквы: О = 6, Д = 8, И = 2, Н = 3 и М = 1, Н = 3, О = 6, Г = 4, О = 6. Каждая буква получила одну и ту же цифру в обоих словах, все шесть цифр разные. Ответ: ОДИН = 6823, МНОГО = 13646, и решение единственное. Почему приём законен — пять правил, на которых держится вся разрядная запись. Первое: буква вместо цифры — это не вольность, а сокращение, пока цифра неизвестна, её обозначают буквой, и одна и та же буква в одном ребусе всегда прячет одну и ту же цифру, иначе у одного знака было бы два разных значения и запись перестала бы быть числом. Второе: разные буквы прячут разные цифры — это условие ребуса, и подстановка «А = 2 и В = 2» для разных букв отбрасывается не по прихоти, а по правилу. Третье: первая буква числа не ноль, потому что числа не записывают с ведущего нуля, иначе 05 — это просто 5, а разрядов оказалось бы меньше, чем букв. Четвёртое: перенос из разряда в следующий равен только 0 или 1 и никогда не больше, ведь самое большее, что может уйти в следующий разряд, — это 9 + 9 + 1 = 19, то есть единица. Пятое: если при сложении двух чисел получилось на один знак больше, то новая старшая цифра — это ровно перенос, то есть 1; поэтому появление новой буквы М в слове МНОГО сразу даёт М = 1. Из этих пяти правил и вырастает весь разбор: он не подбирает цифры, а выводит их по одной. Частая ошибка — дать одной букве две разные цифры: подставив 6824, получают 13648, и тогда буква Н равна и 4, и 3. Вторая ошибка — забыть про перенос из разряда тысяч и подбирать М как обычную цифру: без переноса сумма двух четырёхзначных чисел осталась бы четырёхзначной. Третья ошибка — переставить цифры местами и получить 6832: тогда И = 3 и Н = 2, в разряде единиц Н + Н = 2 + 2 = 4, а буква О должна быть равна 6 — проверка сразу это показывает. Четвёртая ошибка — ответить числом 13646: это не ОДИН, а МНОГО, то есть сумма, а не загаданное слово; в вопросе спрашивают именно про ОДИН. Пятая ошибка — забыть про перенос из разряда единиц в десятки: в этом ребусе его нет (c₁ = 0), но проверить это нужно, а не предполагать. Как проверить себя: сложить найденное число само с собой столбиком и сверить каждую цифру с её буквой. Второй способ — полный перебор: компьютер переберёт все 10 · 9 · 8 · 7 · 6 · 5 = 151 200 расстановок шести цифр и найдёт ровно одну подходящую. Перебор по разрядам короче: он не перебирает варианты, а выводит цифры по одной и попутно доказывает, что других решений нет.'},

      {k:'удар', type:'short', t:'Ребус УДАР + УДАР = ДРАКА',
       q:'То же правило: одинаковая буква — одна и та же цифра. Расшифруй ребус и запиши числом, чему равно слово УДАР. Ответ — число.',
       ans:'8126', alts:['8126', '8 126'],
       ph:'чему равен УДАР',
       why:'Шаг 1. В ответе пять знаков, а складывали два четырёхзначных числа. Значит, из разряда тысяч в пятый разряд перешёл перенос, и этот перенос записан буквой Д в начале слова ДРАКА. Перенос всегда равен 1, поэтому Д = 1. Здесь и спрятана главная ловушка: буква Д стоит в слове УДАР в разряде сотен, а в слове ДРАКА — в старшем разряде, и это одна и та же буква, то есть одна и та же цифра. Шаг 2. Разряд сотен: Д + Д + c₂ = А + 10c₃, то есть 2 + c₂ = А + 10c₃. Слева не больше 3, значит переноса из сотен нет (c₃ = 0), а А = 2 + c₂: либо А = 2, если переноса из десятков нет, либо А = 3, если перенос есть. Шаг 3. Разряд десятков: А + А + c₁ = К + 10c₂. Если c₂ = 1, то А = 3 и 6 + c₁ = К + 10, а это невозможно: слева не больше 7, справа не меньше 10. Значит, c₂ = 0, А = 2 и К = 4 + c₁, то есть К равно 4 или 5. Шаг 4. Разряд единиц: Р + Р = А + 10c₁, то есть 2Р = 2 + 10c₁. Если c₁ = 0, то Р = 1, но 1 уже занята буквой Д, а разные буквы обозначают разные цифры. Значит, c₁ = 1, тогда 2Р = 12 и Р = 6, а К = 4 + 1 = 5. Шаг 5. Разряд тысяч: У + У + c₃ = Р + 10c₄, где c₄ — тот самый перенос в пятый разряд, равный Д = 1. Переноса из сотен нет (c₃ = 0), поэтому 2У = Р + 10 = 6 + 10 = 16, откуда У = 8. Шаг 6. Таблица «буква → цифра»: Д = 1 (шаг 1), А = 2 (шаг 3), К = 5 и Р = 6 (шаг 4), У = 8 (шаг 5) — все пять цифр разные, ни одна не повторяется. Шаг 7. Проверка: 8126 + 8126 = 16252, то есть Д = 1, Р = 6, А = 2, К = 5, А = 2 — сходится с УДАР = 8126. Ответ: УДАР = 8126, ДРАКА = 16252. Частая ошибка — считать Д просто одной из цифр и подбирать её перебором, забыв, что в старшем разряде ответа может стоять только перенос, а перенос равен 1. Вторая ошибка — остановиться на Р = 1 и не заметить, что тогда Д и Р — одна и та же цифра, чего правило не разрешает. Третья ошибка — забыть перенос из разряда единиц в десятки: без него 2Р = 2, Р = 1, и вся цепочка рушится. Как проверить себя: сложить 8126 + 8126 письменно столбиком и сверить каждую цифру ответа с её буквой, особенно Д. Второй способ — полный перебор: компьютер проверит все 10 · 9 · 8 · 7 · 6 = 30 240 расстановок и найдёт ровно одну. Рассуждение по разрядам короче и, главное, объясняет, почему решение одно.'},

      {k:'книга', type:'multi', t:'Ребус КНИГА + КНИГА = НАУКА',
       q:'Отметь все числа, которые могут стоять вместо слова КНИГА. Помни: одинаковые буквы — одинаковые цифры, разные буквы — разные цифры, первая буква числа не ноль.',
       opts:['25160', '25161', '25310', '25360', '25410', '25460'],
       ans:['25160', '25310', '25360', '25410', '25460'],
       why:'Шаг 1. Разряд единиц: А + А = А. Буква А стоит и в слагаемом, и в ответе: 2А оканчивается на А. Это возможно только при А = 0 (если бы 2А равнялось А + 10, то А было бы равно 10, а это не цифра). Значит, А = 0, и переноса из единиц в десятки нет. Шаг 2. Разряд тысяч: Н + Н + c₃ = А + 10c₄ = 10c₄, где c₄ — перенос в пятый разряд. Слева не меньше 2, значит перенос есть: c₄ = 1, и 2Н + c₃ = 10. Из двух значений c₃ подходит только 0 (при c₃ = 1 получилось бы 2Н = 9, а это не целое). Значит, Н = 5 и переноса из сотен нет. Шаг 3. Разряд десятков тысяч: К + К + c₄ = Н, то есть 2К + 1 = 5, откуда К = 2. Шаг 4. Разряд десятков: Г + Г = К + 10c₂, то есть 2Г = 2 + 10c₂. Возможны ровно два случая: переноса нет (c₂ = 0) и тогда Г = 1, или перенос есть (c₂ = 1) и тогда 2Г = 12, то есть Г = 6. Шаг 5. Разряд сотен: И + И + c₂ = У + 10c₃. Переноса из сотен нет (c₃ = 0), значит У = 2И + c₂. Теперь нужно честно перебрать цифру И — и вот здесь важно не остановиться на первом найденном решении. Шаг 6. Случай c₂ = 0, Г = 1, У = 2И. Цифры 0, 1, 2, 5 уже заняты (это А, Г, К, Н), у И остаются 3, 4, 6, 7, 8, 9, но 2И не больше 9, значит И равно 3 или 4. И = 3 даёт У = 6: 25310 + 25310 = 50620. И = 4 даёт У = 8: 25410 + 25410 = 50820. Шаг 7. Случай c₂ = 1, Г = 6, У = 2И + 1. Цифры 0, 2, 5, 6 заняты, у И остаются 1, 3, 4, 7, 8, 9, но 2И + 1 не больше 9, значит И равно 1, 3 или 4. И = 1 даёт У = 3: 25160 + 25160 = 50320. И = 3 даёт У = 7: 25360 + 25360 = 50720. И = 4 даёт У = 9: 25460 + 25460 = 50920. Шаг 8. Проверка каждого решения: 25160 · 2 = 50320, 25310 · 2 = 50620, 25360 · 2 = 50720, 25410 · 2 = 50820, 25460 · 2 = 50920. В каждом ответе буквы читаются теми же цифрами: Н = 5, А = 0, К = 2, У — своя цифра, Г — своя. Всего ровно пять решений, и других нет: мы разобрали оба случая для c₂ и все допустимые значения И. Частая ошибка — остановиться на первом подходящем числе и написать только его: у этого ребуса решений пять, и все они равноправны. Вторая ошибка — испугаться цифры 0 у буквы А: ноль запрещён только на первом месте числа, а в слове КНИГА буква А стоит в середине и в конце — это законно. Третья ошибка — не проверить, что одни и те же буквы в двух словах получили одну цифру: в слове НАУКА стоят те же К, Н, А, У, что и в слове КНИГА. Как проверить себя: подставить каждое найденное число в ребус и сложить столбиком; если хоть одна буква получила разные цифры в двух словах, число не подходит. Второй способ — полный перебор: компьютер переберёт все 10 · 9 · 8 · 7 · 6 = 30 240 расстановок пяти цифр и найдёт те же пять решений. Этот ребус — хороший пример того, что у криптарифма не всегда ровно одно решение, и проверять это нужно.'},

      {k:'перестановка', type:'short', t:'Ребус АБ + БА = 121',
       q:'АБ — двузначное число, БА — то же число с переставленными цифрами. Одинаковые буквы — одинаковые цифры, разные буквы — разные. Чему равна сумма А + Б? Ответ — число.',
       ans:'11', alts:['11', 'одиннадцать'],
       ph:'сумма А + Б',
       why:'Шаг 1. Запишем ребус числами: АБ — это двузначное число, в котором А десятков и Б единиц, то есть 10А + Б. БА — то же самое с переставленными цифрами: 10Б + А. Шаг 2. Складываем: (10А + Б) + (10Б + А) = 11А + 11Б = 11 · (А + Б). Это и есть главная мысль: сумма числа и его перевёртыша всегда делится на 11, потому что каждая цифра попадает один раз в десятки и один раз в единицы. Шаг 3. По условию 11 · (А + Б) = 121, значит А + Б = 121 : 11 = 11. Ответ: сумма равна 11. Шаг 4. Найдём все решения — а их несколько. Нужны две разные цифры, которые в сумме дают 11, и ни одна из них не ноль (ноль не может стоять первой цифрой двузначного числа). Таких пар четыре: 2 и 9, 3 и 8, 4 и 7, 5 и 6 — и каждая пара даёт два числа, потому что цифры можно поменять местами. Всего восемь решений: АБ = 29, 38, 47, 56, 65, 74, 83, 92. Шаг 5. Проверим каждое: 29 + 92 = 121, 38 + 83 = 121, 47 + 74 = 121, 56 + 65 = 121, а дальше те же суммы в обратном порядке. Сошлось. Частая ошибка — написать одно решение и остановиться: ребус симметричный, и если подходит 56 + 65, то подходит и 65 + 56. Вторая ошибка — решить, что раз ребус симметричный, то А = Б: тогда 11 · (А + А) = 121, то есть 22А = 121, а 121 на 22 не делится — значит, А и Б обязательно разные. Третья ошибка — взять пару 0 и 11 или 1 и 10: в паре должны стоять две цифры, а 10 и 11 не цифры. Как проверить себя: подставить пару, сложить столбиком и отдельно посмотреть, что цифры разные и ни одна не стоит первой нулём. Второй способ — полный перебор: 90 возможных двузначных чисел, каждое складываем с перевёрнутым и отбираем те, где сумма равна 121; компьютер находит те же восемь. Рассуждение через 11 · (А + Б) короче: оно сразу говорит и про делимость на 11, и про то, что решений много.'},

      {k:'одинаковые', type:'short', t:'Ребус АА + ББ = 110',
       q:'Восстанови цифры в равенстве АА + ББ = 110. Одинаковые буквы — одинаковые цифры, разные буквы — разные цифры. Чему равна сумма А + Б? Ответ — число.',
       ans:'10', alts:['10', 'десять'],
       ph:'сумма А + Б',
       why:'Шаг 1. Число из двух одинаковых цифр устроено просто: АА = 10А + А = 11А. Точно так же ББ = 11Б. Шаг 2. Складываем: 11А + 11Б = 11 · (А + Б). По условию это равно 110, значит А + Б = 110 : 11 = 10. Ответ: сумма равна 10. Шаг 3. Перечислим все решения — пары разных цифр с суммой 10, в которых ни одна цифра не ноль: 1 и 9, 2 и 8, 3 и 7, 4 и 6, а также обратные пары 6 и 4, 7 и 3, 8 и 2, 9 и 1. Всего восемь решений: 11 + 99, 22 + 88, 33 + 77, 44 + 66, 66 + 44, 77 + 33, 88 + 22, 99 + 11 — в каждой строке получается 110. Шаг 4. Ловушка. Очень хочется написать 55 + 55 = 110: арифметика здесь верная, 110 действительно получается. Но А и Б — разные буквы, а мы дали им одну и ту же цифру 5. Правило «разные буквы — разные цифры» нарушено, поэтому пара 5 и 5 решением не считается, хотя сумма А + Б = 10 от этого не меняется. Шаг 5. Проверим пару 4 и 6: 44 + 66 = 110 — верно, буквы получили разные цифры, значит 44 и 66 подходят. А теперь 55 и 55: сложение верное, а буквы одинаковые — не подходит. Частая ошибка — принять 55 + 55 = 110 за ответ и остановиться. Вторая ошибка — забыть, что первой цифрой числа ноль быть не может: пара 0 и 10 не годится ещё и потому, что 10 — не цифра. Третья ошибка — перепутать правила: решить, что одинаковые цифры у разных букв разрешены, а одинаковые буквы могут иметь разные цифры; в ребусе всё ровно наоборот. Как проверить себя: подставить пару, сложить столбиком и отдельно проверить, что каждая буква получила свою цифру и все цифры разные. Второй способ — полный перебор: 90 пар цифр, для каждой проверяем 11А + 11Б = 110; компьютер найдёт ровно восемь решений и покажет, что 55 + 55 отброшено именно из-за повторяющейся цифры.'},

      {k:'ловушка', type:'single', t:'Ребус-ловушка АБ + А = ВВ',
       q:'Мишутка подставил А = 2, Б = 0, В = 2 и получил 20 + 2 = 22 — сходится! Почему это не решение ребуса?',
       opts:['Потому что А и В — разные буквы, а цифра у них одна и та же; другого решения у ребуса нет.',
             'Потому что 20 + 2 на самом деле не равно 22.',
             'Потому что цифру 0 в ребусах использовать нельзя.',
             'Потому что буква А должна быть больше буквы В.'],
       ans:'Потому что А и В — разные буквы, а цифра у них одна и та же; другого решения у ребуса нет.',
       why:'Шаг 1. Сначала проверим счёт. 20 + 2 = 22 — это верно, ошибки в арифметике нет. Значит, искать надо не в числах, а в буквах. Шаг 2. Мишутка дал букве А цифру 2 и букве В тоже цифру 2. Но А и В — разные буквы, а в ребусе разные буквы обозначают разные цифры. Уже это делает подстановку неверной: 20 + 2 = 22 не расшифровывает ребус, а нарушает его правило. Шаг 3. Проверим, нет ли другой подстановки. Запишем ребус числами: АБ = 10А + Б, ВВ = 11В. Тогда (10А + Б) + А = 11В, то есть 11А + Б = 11В, откуда Б = 11 · (В − А). Слева стоит цифра, то есть число от 0 до 9. Справа стоит число, кратное 11: 0, 11, 22 и так далее. В промежуток от 0 до 9 попадает только 0. Значит, В − А = 0, то есть В = А, и при этом Б = 0. Но равенство В = А как раз и запрещено: буквы разные. Шаг 4. Вывод: у ребуса АБ + А = ВВ решений нет вообще. Ловушка в том, что подстановка Мишутки арифметически верна и проверку сложением проходит; чтобы её отвергнуть, нужно проверить не только сумму, но и буквы. Частая ошибка — решить, что раз числа сложились, то ребус решён. Вторая ошибка — отвергнуть подстановку не по той причине: сказать «ноль в ребусах нельзя», хотя ноль здесь стоит не первым и сам по себе он законен. Третья ошибка — подбирать дальше наугад, не доказав, что решений нет. Как проверить себя: после каждой подстановки выписать рядом буквы и их цифры и посмотреть, все ли цифры разные. Второй способ — полный перебор: 90 пар А и Б (А от 1 до 9, Б от 0 до 9), для каждой считаем 10А + Б + А и смотрим, получилось ли число из двух одинаковых цифр. Компьютер не находит ни одной пары: решений действительно нет.'},

      {k:'все33', type:'order', t:'Найди все решения: АБ + БА = 33',
       q:'Расставь шаги решения по порядку — тогда видно, почему у ребуса ровно два решения. Нажимай на шаги по очереди, цифра покажет их место.',
       items:['Приводим подобные: 10А + Б + 10Б + А = 11 · (А + Б)',
              'Вывод: решений ровно два — АБ = 12 и АБ = 21',
              'Записываем ребус числами: АБ = 10А + Б, БА = 10Б + А',
              'Подставляем и проверяем: 12 + 21 = 33, потом 21 + 12 = 33',
              'Делим обе части на 11: А + Б = 3',
              'Перебираем пары разных цифр с суммой 3: подходит только 1 и 2'],
       ans:['Записываем ребус числами: АБ = 10А + Б, БА = 10Б + А',
            'Приводим подобные: 10А + Б + 10Б + А = 11 · (А + Б)',
            'Делим обе части на 11: А + Б = 3',
            'Перебираем пары разных цифр с суммой 3: подходит только 1 и 2',
            'Подставляем и проверяем: 12 + 21 = 33, потом 21 + 12 = 33',
            'Вывод: решений ровно два — АБ = 12 и АБ = 21'],
       why:'Порядок шагов и есть решение. Сначала ребус записывают числами — без этого перебирать нечего: АБ = 10А + Б, БА = 10Б + А. Потом слагаемые складывают и приводят подобные: 10А + Б + 10Б + А = 11А + 11Б = 11 · (А + Б). Дальше делят обе части на 11 и получают А + Б = 3. И только после этого наступает перебор: выписывают все пары разных цифр с суммой 3 — это единственная пара 1 и 2. Каждую пару проверяют подстановкой: 12 + 21 = 33 подходит, 21 + 12 = 33 тоже подходит. Вывод: решений ровно два, АБ = 12 и АБ = 21. Частая ошибка — написать только 12 и забыть, что цифры можно поменять местами: тогда второе решение потеряно. Вторая ошибка — взять А = 3 и Б = 0: 30 + 3 = 33 действительно верно, но запись БА превратилась бы в 03, а это не двузначное число — ноль не может стоять первой цифрой. Третья ошибка — перебирать все 90 двузначных чисел наугад, не получив сначала уравнение А + Б = 3: уравнение сокращает перебор до одной пары. Как проверить себя: подставить каждое найденное число в ребус, сложить столбиком и отдельно проверить, что буквы получили разные цифры и ни одна не оказалась первой нулём. Второй способ — полный перебор компьютером: он проверит все 90 пар и найдёт те же два решения. Рассуждение с делением на 11 короче и объясняет, откуда взялась сумма 3.'},

      {k:'финал', type:'open', t:'Свой ребус: решить и объяснить единственность',
       q:'Реши ребус ББ + ББ = ВВА: чему равны А, Б и В? Объясни, почему это решение единственное — почему В не может быть другой цифрой и почему Б равно именно 5. Потом придумай свой похожий ребус с двумя-тремя буквами и проверь перебором, сколько у него решений. Запиши 4–6 предложениями.',
       ph:'цифры и объяснение единственности',
       model:'ББ = 11Б, а ВВА = 110В + А. Получаем уравнение 22Б = 110В + А. Дальше рассуждаем про В. Если В = 0, то 22Б = А, а А не больше 9, значит Б = 0 — но буква Б стоит первой в слове ББ, а ноль первым быть не может. Если В больше или равно 2, то 110В не меньше 220, а 22Б при Б не больше 9 не превосходит 198 — не хватает. Значит, В = 1, и тогда 22Б = 110 + А, откуда А = 22Б − 110. Чтобы А было цифрой, нужно 110 ≤ 22Б ≤ 119; между 110 и 119 на 22 делится только само 110, значит Б = 5 и А = 0. Проверка: 55 + 55 = 110, то есть А = 0, Б = 5, В = 1 — все три цифры разные. Решение единственное: В мы перебрали полностью (0, 1 и всё, что не меньше 2), а при В = 1 значение Б оказалось единственным. Свой ребус: АБ + БА = 55 — перебор даёт четыре решения: 14 + 41, 23 + 32, 32 + 23 и 41 + 14, потому что сумма всегда равна 11 · (А + Б), а здесь А + Б = 5. Решение не одно — и это тоже правильный ответ: главное проверить перебором и честно сказать, сколько решений нашлось.',
       criteria:['Названы все три цифры: А = 0, Б = 5, В = 1.',
                 'Есть проверка сложением: 55 + 55 = 110.',
                 'Объяснено, почему В = 1: при В = 0 получается Б = 0 (ноль первым нельзя), при В ≥ 2 правая часть не помещается в 22Б при Б ≤ 9.',
                 'Объяснено, почему Б = 5: из 22Б = 110 + А и 0 ≤ А ≤ 9 следует 110 ≤ 22Б ≤ 119.',
                 'Придуман свой ребус и честно указано, сколько у него решений — перебором, а не на глаз.'],
       why:'Развёрнутый ответ проверяют по критериям, а не машиной. Сравни свой текст с образцом: без первой строки нет ответа, без второй нечем доказать, что он верный, без третьей и четвёртой не доказана единственность — а это главное в задании, и без пятой не выполнена вторая половина работы, свой ребус. Обратите внимание на приём: мы не перебирали все 90 пар, а рассуждали про В — и именно поэтому смогли сказать «других решений нет», а не «я не нашёл других». Так и проверяют единственность: разбирают все случаи и показывают, что лишних не осталось.'}
    ],
    check:{q:'Ребус АА + Б = 100. Какие цифры подходят?',
      choices:['А = 9, Б = 1', 'А = 8, Б = 2', 'А = 1, Б = 9', 'Ни одна пара не подходит'],
      ans:0,
      exp:'АА — это 11 · А, значит 11А + Б = 100. Из цифр подходит только А = 9: 11 · 9 = 99 и Б = 1. Проверим остальные: при А = 8 получается 88 + Б = 100, то есть Б = 12 — не цифра; при А = 1 получается 11 + Б = 100, то есть Б = 89 — тоже не цифра. Ответ: А = 9, Б = 1, и он единственный.'},
    tasks:[
      {q:'Ребус АБ + БА = 44. Чему равна сумма А + Б?', kind:'unit', ans:4, tol:0,
       hints:['Запиши ребус числами: АБ = 10А + Б, БА = 10Б + А.',
              'Сумма равна 11 · (А + Б), значит 11 · (А + Б) = 44.',
              '44 : 11 = 4. Проверка: 13 + 31 = 44 и 31 + 13 = 44.'], sol:'4'},
      {q:'Ребус БА + БА = 100. Чему равно число БА?', kind:'unit', ans:50, tol:0,
       hints:['БА + БА — это 2 · БА.',
              'Значит, 2 · БА = 100, откуда БА = 50.',
              'Проверка: 50 + 50 = 100; буквы Б = 5 и А = 0 разные, ноль стоит не первым.'], sol:'50'},
      {q:'Ребус АБ + БА = 33. Сколько у него решений?', kind:'unit', ans:2, tol:0,
       hints:['Сумма равна 11 · (А + Б) = 33, значит А + Б = 3.',
              'Пары разных цифр с суммой 3: только 1 и 2.',
              'Проверка: 12 + 21 = 33 и 21 + 12 = 33 — ровно два решения.'], sol:'2'}
    ]
  });
})();
